1	package checks
2	
3	import (
4		"context"
5		"strconv"
6		"strings"
7	
8		"lava-sensor-exercise/sensor/internal/probe"
9		"lava-sensor-exercise/sensor/internal/scan"
10	)
11	
12	// STORAGE_POSTURE is about data-at-rest and decommissioning hygiene on rented
13	// hardware. No check in this file ever opens a block device: what is on a disk
14	// is deliberately out of scope, and saying so is part of the answer.
15	
16	// ---------------------------------------------------------------------------
17	// DISK_ENCRYPTION_AT_REST
18	// ---------------------------------------------------------------------------
19	
20	type diskEncryptionAtRest struct{ meta }
21	
22	type dmDevice struct {
23		Name     string `json:"name"`
24		SysfsDir string `json:"sysfs_path"`
25		DMName   string `json:"dm_name,omitempty"`
26		DMUUID   string `json:"dm_uuid,omitempty"`
27		Crypt    bool   `json:"crypt"`
28		Errno    string `json:"errno,omitempty"`
29	}
30	
31	type blindSpot struct {
32		Mechanism  string `json:"mechanism"`
33		WhyUnknown string `json:"why_unknown"`
34		Evidence   string `json:"evidence_path_or_errno"`
35	}
36	
37	func (c diskEncryptionAtRest) Run(ctx context.Context, env *scan.Env) scan.Result {
38		var r scan.Result
39		finish := func(out scan.Result) scan.Result {
40			out.Observations, out.Fields = r.Observations, r.Fields
41			return out
42		}
43		// The verdict is scoped to dm-crypt/LUKS. "No dm mapping" is not "the disks
44		// are unencrypted" (L30) and the wording never says otherwise.
45		r.Field("scope", "dm-crypt/LUKS as visible to the kernel's device-mapper layer")
46	
47		blockNames, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
48		blockObs.LoadBearing = true
49		r.Add(blockObs)
50		mapperNames, mapperObs := env.Files.ReadDirNames("/dev/mapper", 512)
51		r.Add(mapperObs)
52		mounts := env.Mounts()
53		r.Add(mounts.Obs)
54	
55		var dms []dmDevice
56		cryptFound := false
57		uuidUnreadable := false
58		for _, n := range blockNames {
59			if !strings.HasPrefix(n, "dm-") {
60				continue
61			}
62			d := dmDevice{Name: n, SysfsDir: "/sys/block/" + n + "/dm"}
63			uuid, uObs := env.Files.ReadTrimmed("/sys/block/"+n+"/dm/uuid", probe.Tiny)
64			name, _ := env.Files.ReadTrimmed("/sys/block/"+n+"/dm/name", probe.Tiny)
65			d.DMUUID, d.DMName = uuid, name
66			if uObs.Status != probe.StatusOK {
67				d.Errno = uObs.Reason()
68				uuidUnreadable = true
69			}
70			// cryptsetup's own convention: the mapping's uuid is CRYPT-<type>-...
71			if strings.HasPrefix(uuid, "CRYPT-") {
72				d.Crypt, cryptFound = true, true
73			}
74			dms = append(dms, d)
75		}
76		r.Field("dm_devices", dms)
77		r.Field("dm_devices_found", int64(len(dms)))
78		r.Field("dev_mapper_entries", mapperNames)
79	
80		// The backing chain of every real mount.
81		type mountChain struct {
82			Mountpoint string   `json:"mountpoint"`
83			Source     string   `json:"source"`
84			FSType     string   `json:"fstype"`
85			Backing    []string `json:"backing_devices"`
86			Encrypted  bool     `json:"encrypted_by_dm_crypt"`
87		}
88		var chains []mountChain
89		rootEncrypted := false
90		for _, m := range mounts.Entries {
91			if !isRealFilesystem(m.FSType) {
92				continue
93			}
94			backing := backingDevices(env, m.MajorMinor)
95			mc := mountChain{Mountpoint: m.MountPoint, Source: m.Source, FSType: m.FSType, Backing: backing}
96			for _, b := range backing {
97				for _, d := range dms {
98					if d.Name == b && d.Crypt {
99						mc.Encrypted = true
100					}
101				}
102			}
103			if m.MountPoint == "/" {
104				rootEncrypted = mc.Encrypted
105			}
106			chains = append(chains, mc)
107		}
108		r.Field("mount_chain", chains)
109	
110		// Named blind spots, each with its own reason: an unknown that is not named
111		// is indistinguishable from a claim.
112		spots := []blindSpot{
113			{"self-encrypting drive / TCG Opal",
114				"every IOC_OPAL_* ioctl is gated on CAP_SYS_ADMIN and the kernel exposes no Opal state in sysfs; the drive model string cannot substitute, because vendors ship SED and non-SED SKUs under the same base part number",
115				"no sysfs attribute exists to read"},
116			{"filesystem-level encryption (ext4 fscrypt)",
117				"whether a filesystem uses fscrypt is recorded in its superblock, which needs root or dumpe2fs to read; kernel support for the feature is not use of it",
118				"/sys/fs/ext4/features/encryption (support only)"},
119			{"ZFS and btrfs native encryption",
120				"reported only where such a filesystem is mounted; the property lives in the pool or subvolume metadata",
121				"/proc/self/mountinfo fstype"},
122		}
123		if fe := env.Files.Stat("/sys/fs/ext4/features/encryption"); fe.Status == probe.StatusOK {
124			r.Field("ext4_fscrypt_kernel_support", true)
125		}
126		r.Field("blind_spots", spots)
127		if ct := env.Files.Stat("/etc/crypttab"); ct.Status == probe.StatusOK {
128			r.Add(ct)
129			r.Field("crypttab_present", true)
130		}
131	
132		switch {
133		case blockObs.Status != probe.StatusOK || mounts.Obs.Status != probe.StatusOK:
134			return finish(scan.Unknown(reasonOf(blockObs, mounts.Obs),
135				"the block device list or the mount table could not be read, so the backing chain of the mounted filesystems is unresolved and dm-crypt use can neither be confirmed nor ruled out"))
136		case uuidUnreadable:
137			return finish(scan.Unknown(scan.ReasonEACCES,
138				"a device-mapper mapping exists whose dm/uuid could not be read, so whether it is a dm-crypt mapping is unknown"))
139		case rootEncrypted:
140			return finish(scan.Pass(
141				"the root filesystem's backing chain reaches a device-mapper mapping whose dm/uuid carries the CRYPT- prefix, so dm-crypt/LUKS is in use for it"))
142		case cryptFound:
143			return finish(scan.Fail(scan.ReasonPolicy,
144				"dm-crypt/LUKS mappings exist on this machine but the root filesystem's backing chain does not pass through one, so the root filesystem is not protected by block-level encryption the kernel can see"))
145		default:
146			return finish(scan.Fail(scan.ReasonPolicy,
147				"the device-mapper and block device listings both completed and contain no CRYPT- mapping, so dm-crypt/LUKS is provably not in use for any mounted filesystem; this statement is scoped to dm-crypt/LUKS and does not assert that the media is unencrypted — the named blind spots in the evidence say what remains unknown"))
148		}
149	}
150	
151	func isRealFilesystem(fstype string) bool {
152		switch fstype {
153		case "proc", "sysfs", "devtmpfs", "devpts", "tmpfs", "cgroup", "cgroup2", "securityfs",
154			"pstore", "bpf", "configfs", "debugfs", "tracefs", "fusectl", "mqueue", "hugetlbfs",
155			"binfmt_misc", "autofs", "efivarfs", "ramfs", "rpc_pipefs", "nsfs", "overlay", "squashfs",
156			"9p", "drvfs", "none":
157			return false
158		}
159		return true
160	}
161	
162	// backingDevices walks from a mount's major:minor down to the physical devices
163	// underneath it, through slaves/ links.
164	func backingDevices(env *scan.Env, majmin string) []string {
165		name := blockNameFor(env, majmin)
166		if name == "" {
167			return []string{}
168		}
169		seen := map[string]bool{}
170		var out []string
171		var walk func(string, int)
172		walk = func(n string, depth int) {
173			if depth > 8 || seen[n] {
174				return
175			}
176			seen[n] = true
177			out = append(out, n)
178			slaves, obs := env.Files.ReadDirNames("/sys/block/"+n+"/slaves", 64)
179			if obs.Status != probe.StatusOK {
180				// A partition's parent is its containing directory, not a slave.
181				if parent := wholeDiskOf(env, n); parent != "" && parent != n {
182					walk(parent, depth+1)
183				}
184				return
185			}
186			for _, s := range slaves {
187				walk(s, depth+1)
188			}
189		}
190		walk(name, 0)
191		return out
192	}
193	
194	// blockNameFor resolves a major:minor to a kernel block device name, including
195	// partitions, without opening anything.
196	func blockNameFor(env *scan.Env, majmin string) string {
197		names, obs := env.Files.ReadDirNames("/sys/block", 1024)
198		if obs.Status != probe.StatusOK {
199			return ""
200		}
201		for _, n := range names {
202			if v, o := env.Files.ReadTrimmed("/sys/block/"+n+"/dev", probe.Tiny); o.Status == probe.StatusOK && v == majmin {
203				return n
204			}
205			parts, po := env.Files.ReadDirNames("/sys/block/"+n, 1024)
206			if po.Status != probe.StatusOK {
207				continue
208			}
209			for _, p := range parts {
210				if !strings.HasPrefix(p, n) || p == n {
211					continue
212				}
213				if v, o := env.Files.ReadTrimmed("/sys/block/"+n+"/"+p+"/dev", probe.Tiny); o.Status == probe.StatusOK && v == majmin {
214					return p
215				}
216			}
217		}
218		return ""
219	}
220	
221	func wholeDiskOf(env *scan.Env, part string) string {
222		names, obs := env.Files.ReadDirNames("/sys/block", 1024)
223		if obs.Status != probe.StatusOK {
224			return ""
225		}
226		for _, n := range names {
227			if n != part && strings.HasPrefix(part, n) {
228				return n
229			}
230		}
231		return ""
232	}
