234	// ---------------------------------------------------------------------------
235	// ROOT_FILESYSTEM_REDUNDANCY
236	// ---------------------------------------------------------------------------
237	
238	type rootFilesystemRedundancy struct{ meta }
239	
240	type mdArray struct {
241		Name      string `json:"name"`
242		Level     string `json:"level,omitempty"`
243		Degraded  string `json:"degraded,omitempty"`
244		RaidDisks string `json:"raid_disks,omitempty"`
245		Errno     string `json:"errno,omitempty"`
246	}
247	
248	var redundantLevels = map[string]bool{"raid1": true, "raid5": true, "raid6": true, "raid10": true}
249	
250	func (c rootFilesystemRedundancy) Run(ctx context.Context, env *scan.Env) scan.Result {
251		var r scan.Result
252		finish := func(out scan.Result) scan.Result {
253			out.Observations, out.Fields = r.Observations, r.Fields
254			return out
255		}
256	
257		mounts := env.Mounts()
258		mounts.Obs.LoadBearing = true
259		r.Add(mounts.Obs)
260		var rootMM, rootFS, rootSrc string
261		for _, m := range mounts.Entries {
262			if m.MountPoint == "/" {
263				rootMM, rootFS, rootSrc = m.MajorMinor, m.FSType, m.Source
264			}
265		}
266		if rootMM == "" {
267			return finish(scan.Unknown(scan.ReasonParse,
268				"the root filesystem could not be located in the mount table, so its backing chain is unresolved"))
269		}
270		backing := backingDevices(env, rootMM)
271		r.Field("root_mount", map[string]string{"source": rootSrc, "fstype": rootFS, "major_minor": rootMM})
272		r.Field("backing_devices", backing)
273	
274		// md arrays. /proc/mdstat always lists the compiled-in personalities, so a
275		// populated Personalities: line is not an array (T-S2).
276		mdstat := env.Files.Read("/proc/mdstat", probe.Small)
277		r.Add(mdstat)
278		blockNames, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
279		r.Add(blockObs)
280		var arrays []mdArray
281		for _, n := range blockNames {
282			if !strings.HasPrefix(n, "md") {
283				continue
284			}
285			a := mdArray{Name: n}
286			a.Level, _ = env.Files.ReadTrimmed("/sys/block/"+n+"/md/level", probe.Tiny)
287			a.Degraded, _ = env.Files.ReadTrimmed("/sys/block/"+n+"/md/degraded", probe.Tiny)
288			a.RaidDisks, _ = env.Files.ReadTrimmed("/sys/block/"+n+"/md/raid_disks", probe.Tiny)
289			arrays = append(arrays, a)
290		}
291		r.Field("md_arrays", arrays)
292		if mdstat.Status == probe.StatusOK {
293			r.Field("mdstat_excerpt", excerptLines(mdstat.Value, 12))
294			r.Field("mdstat_note", "/proc/mdstat always lists the compiled-in personalities; a populated Personalities: line is not an array")
295		}
296	
297		// A hardware RAID controller presents one logical device and its health
298		// needs a vendor CLI. Gate on the PCI class, never on a controller name.
299		var raidControllers []string
300		if devs, obs := env.Files.ReadDirNames("/sys/bus/pci/devices", 1024); obs.Status == probe.StatusOK {
301			for _, d := range devs {
302				cls, o := env.Files.ReadTrimmed("/sys/bus/pci/devices/"+d+"/class", probe.Tiny)
303				if o.Status != probe.StatusOK {
304					continue
305				}
306				if strings.HasPrefix(strings.ToLower(cls), "0x0104") {
307					drv, _ := env.Files.ReadLinkBase("/sys/bus/pci/devices/" + d + "/driver")
308					raidControllers = append(raidControllers, d+" (class "+cls+", driver "+firstNonEmpty(drv, "none")+")")
309				}
310			}
311		}
312		r.Field("pci_raid_controllers", raidControllers)
313	
314		// Redundancy layer, decided from the backing chain.
315		layer := "none"
316		degraded := false
317		for _, b := range backing {
318			switch {
319			case strings.HasPrefix(b, "md"):
320				for _, a := range arrays {
321					if a.Name == b && redundantLevels[a.Level] {
322						layer = "md/" + a.Level
323						degraded = a.Degraded != "" && a.Degraded != "0"
324					}
325				}
326			case strings.HasPrefix(b, "dm-"):
327				if uuid, o := env.Files.ReadTrimmed("/sys/block/"+b+"/dm/uuid", probe.Tiny); o.Status == probe.StatusOK && strings.HasPrefix(uuid, "DM-RAID-") {
328					layer = "dm-raid"
329				}
330			}
331		}
332		if rootFS == "btrfs" {
333			if devs, obs := env.Files.ReadDirNames("/sys/fs/btrfs", 64); obs.Status == probe.StatusOK && len(devs) > 0 {
334				r.Field("btrfs_filesystems", devs)
335			}
336			if layer == "none" {
337				return finish(scan.Unknown(scan.ReasonUtilMiss,
338					"the root filesystem is btrfs, whose redundancy profile lives in filesystem metadata that this sensor does not read, so whether it survives a device loss is unknown"))
339			}
340		}
341		if rootFS == "zfs" && layer == "none" {
342			return finish(scan.Unknown(scan.ReasonUtilMiss,
343				"the root filesystem is ZFS, whose vdev layout is not exposed in sysfs, so whether it survives a device loss is unknown"))
344		}
345		r.Field("redundancy_layer", layer)
346	
347		// Idle devices that could provide redundancy make the finding actionable.
348		var spares []string
349		for _, n := range blockNames {
350			if hasAnyPrefix(n, excludedBlockPrefixes) || strings.HasPrefix(n, "dm-") || strings.HasPrefix(n, "md") {
351				continue
352			}
353			if !deviceInUse(env, n, mounts) {
354				spares = append(spares, n)
355			}
356		}
357		r.Field("idle_devices_present", spares)
358	
359		physical := 0
360		for _, b := range backing {
361			if !strings.HasPrefix(b, "dm-") && !strings.HasPrefix(b, "md") {
362				physical++
363			}
364		}
365	
366		switch {
367		case len(raidControllers) > 0 && layer == "none":
368			return finish(scan.Unknown(scan.ReasonUtilMiss,
369				"a PCI RAID controller (class 0104) is present, so the root filesystem's single logical device may be backed by hardware redundancy this operating system cannot see; a vendor CLI would be needed to establish it"))
370		case degraded:
371			return finish(scan.Fail(scan.ReasonPolicy,
372				"the root filesystem sits on a "+layer+" array that is currently degraded, so it may not survive another device loss"))
373		case layer != "none":
374			return finish(scan.Pass("the root filesystem's backing chain passes through a " + layer +
375				" layer reporting zero degraded members, so it survives the loss of a single device"))
376		case blockObs.Status != probe.StatusOK || mdstat.Status != probe.StatusOK:
377			return finish(scan.Unknown(reasonOf(blockObs, mdstat),
378				"the redundancy enumerations did not all complete, so a single-device root cannot be asserted"))
379		case physical <= 1:
380			msg := "the root filesystem resolves to a single physical device (" + strings.Join(backing, " -> ") +
381				") and every redundancy enumeration completed without finding an md array, a dm-raid target or a multi-device pool, so the loss of that device loses the root filesystem"
382			if len(spares) > 0 {
383				msg += "; " + itoa(int64(len(spares))) + " attached device(s) (" + strings.Join(spares, ", ") +
384					") are idle and could provide redundancy. A single-device root may be a deliberate rebuild-on-failure choice"
385			}
386			return finish(scan.Fail(scan.ReasonPolicy, msg))
387		default:
388			return finish(scan.Unknown(scan.ReasonParse,
389				"the root filesystem's backing chain resolved to "+itoa(int64(physical))+
390					" devices without an identifiable redundancy layer, so whether it survives a device loss is unresolved"))
391		}
392	}
393	
394	func excerptLines(s string, n int) string {
395		lines := strings.Split(strings.TrimSpace(s), "\n")
396		if len(lines) > n {
397			lines = lines[:n]
398		}
399		return strings.Join(lines, "\n")
400	}
