402	// ---------------------------------------------------------------------------
403	// UNUSED_ATTACHED_BLOCK_DEVICES
404	// ---------------------------------------------------------------------------
405	
406	type unusedAttachedBlockDevices struct{ meta }
407	
408	type blockDeviceUse struct {
409		Name               string   `json:"name"`
410		SizeBytes          int64    `json:"size_bytes"`
411		Partitions         []string `json:"partitions"`
412		Holders            []string `json:"holders"`
413		Slaves             []string `json:"slaves"`
414		Mountpoints        []string `json:"mountpoints"`
415		UdevFSType         string   `json:"udev_fstype"`
416		UdevRecordPath     string   `json:"udev_record_path"`
417		UdevRecordReadable bool     `json:"udev_record_readable"`
418		InSwap             bool     `json:"in_swap"`
419		InUse              bool     `json:"in_use"`
420		InUseBasis         []string `json:"in_use_basis"`
421	}
422	
423	const remanenceStatement = "unknown by design — the sensor does not open the device to find out what is on it"
424	
425	func (c unusedAttachedBlockDevices) Run(ctx context.Context, env *scan.Env) scan.Result {
426		var r scan.Result
427		finish := func(out scan.Result) scan.Result {
428			out.Observations, out.Fields = r.Observations, r.Fields
429			return out
430		}
431		r.Field("device_not_opened", true)
432		r.Field("remanence", remanenceStatement)
433		r.Field("udev_caveat", "fstype comes from the udev database as recorded at the last uevent, not from a read of the disk; a filesystem created afterwards would be invisible")
434	
435		names, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
436		blockObs.LoadBearing = true
437		r.Add(blockObs)
438		if blockObs.Status != probe.StatusOK {
439			return finish(scan.Unknown(blockObs.Reason(),
440				"/sys/block could not be listed ("+blockObs.Reason()+"), so which block devices are attached is unknown"))
441		}
442		mounts := env.Mounts()
443		r.Add(mounts.Obs)
444		swaps := env.Files.Read("/proc/swaps", probe.Small)
445		r.Add(swaps)
446	
447		var devices []blockDeviceUse
448		var idle []string
449		udevUnreadable := false
450	
451		for _, n := range names {
452			if hasAnyPrefix(n, excludedBlockPrefixes) {
453				continue
454			}
455			d := blockDeviceUse{Name: n, Partitions: []string{}, Holders: []string{}, Slaves: []string{},
456				Mountpoints: []string{}, InUseBasis: []string{}}
457			if v, o := env.Files.ReadTrimmed("/sys/block/"+n+"/size", probe.Tiny); o.Status == probe.StatusOK {
458				if sectors, err := strconv.ParseInt(v, 10, 64); err == nil {
459					d.SizeBytes = sectors * sectorBytes
460				}
461			}
462			if ents, o := env.Files.ReadDirNames("/sys/block/"+n, 1024); o.Status == probe.StatusOK {
463				for _, e := range ents {
464					if e != n && strings.HasPrefix(e, n) && env.Files.Exists("/sys/block/"+n+"/"+e+"/partition") {
465						d.Partitions = append(d.Partitions, e)
466					}
467				}
468			}
469			if hs, o := env.Files.ReadDirNames("/sys/block/"+n+"/holders", 64); o.Status == probe.StatusOK {
470				d.Holders = hs
471			}
472			if sl, o := env.Files.ReadDirNames("/sys/block/"+n+"/slaves", 64); o.Status == probe.StatusOK {
473				d.Slaves = sl
474			}
475			majmin, _ := env.Files.ReadTrimmed("/sys/block/"+n+"/dev", probe.Tiny)
476			d.UdevRecordPath = "/run/udev/data/b" + majmin
477			udevObs := env.Files.Read(d.UdevRecordPath, probe.Small)
478			if udevObs.Status == probe.StatusOK {
479				d.UdevRecordReadable = true
480				for _, ln := range strings.Split(udevObs.Value, "\n") {
481					if k, v, ok := strings.Cut(strings.TrimPrefix(ln, "E:"), "="); ok && k == "ID_FS_TYPE" {
482						d.UdevFSType = v
483					}
484				}
485			} else if udevObs.Status != probe.StatusENOENT {
486				udevUnreadable = true
487			}
488			for _, m := range mounts.Entries {
489				if m.MajorMinor == majmin || strings.Contains(m.Source, "/"+n) {
490					d.Mountpoints = append(d.Mountpoints, m.MountPoint)
491				}
492			}
493			if swaps.Status == probe.StatusOK && strings.Contains(swaps.Value, "/"+n) {
494				d.InSwap = true
495			}
496	
497			if len(d.Partitions) > 0 {
498				d.InUseBasis = append(d.InUseBasis, "has "+itoa(int64(len(d.Partitions)))+" partition(s)")
499			}
500			if len(d.Holders) > 0 {
501				d.InUseBasis = append(d.InUseBasis, "has holders")
502			}
503			if len(d.Mountpoints) > 0 {
504				d.InUseBasis = append(d.InUseBasis, "is mounted")
505			}
506			if d.InSwap {
507				d.InUseBasis = append(d.InUseBasis, "is a swap device")
508			}
509			if d.UdevFSType != "" {
510				d.InUseBasis = append(d.InUseBasis, "udev recorded filesystem type "+d.UdevFSType)
511			}
512			d.InUse = len(d.InUseBasis) > 0
513			if !d.InUse {
514				idle = append(idle, n)
515			}
516			devices = append(devices, d)
517		}
518		r.Field("devices", devices)
519	
520		switch {
521		case mounts.Obs.Status != probe.StatusOK || swaps.Status != probe.StatusOK:
522			return finish(scan.Unknown(reasonOf(mounts.Obs, swaps),
523				"the mount table or the swap list could not be read, so whether every attached device is accounted for is unknown"))
524		case udevUnreadable && len(idle) > 0:
525			return finish(scan.Unknown(scan.ReasonEACCES,
526				"a device has no partition, holder, mount or swap entry, but its udev record could not be read, so whether it carries a filesystem signature is an open question"))
527		case len(idle) > 0:
528			return finish(scan.Fail(scan.ReasonPolicy,
529				"attached but unaccounted for: "+strings.Join(idle, ", ")+
530					" — no partition table and no filesystem signature known to udev, no holder, no mount and no swap entry. "+
531					"Whether prior-tenant data remains on it is "+remanenceStatement))
532		default:
533			return finish(scan.Pass(
534				"every attached physical block device is accounted for by a partition, a mount, a holder relationship, a swap entry or a udev filesystem signature (" +
535					itoa(int64(len(devices))) + " device(s))"))
536		}
537	}
538	
539	func deviceInUse(env *scan.Env, n string, mounts *scan.MountTable) bool {
540		if ents, o := env.Files.ReadDirNames("/sys/block/"+n, 1024); o.Status == probe.StatusOK {
541			for _, e := range ents {
542				if e != n && strings.HasPrefix(e, n) && env.Files.Exists("/sys/block/"+n+"/"+e+"/partition") {
543					return true
544				}
545			}
546		}
547		if hs, o := env.Files.ReadDirNames("/sys/block/"+n+"/holders", 64); o.Status == probe.StatusOK && len(hs) > 0 {
548			return true
549		}
550		majmin, _ := env.Files.ReadTrimmed("/sys/block/"+n+"/dev", probe.Tiny)
551		for _, m := range mounts.Entries {
552			if m.MajorMinor == majmin {
553				return true
554			}
555		}
556		return false
557	}
