559	// ---------------------------------------------------------------------------
560	// MEDIA_HEALTH_VISIBILITY
561	// ---------------------------------------------------------------------------
562	
563	type mediaHealthVisibility struct{ meta }
564	
565	type healthSignal struct {
566		Path  string `json:"path"`
567		Value string `json:"value,omitempty"`
568		Errno string `json:"errno,omitempty"`
569		Clean *bool  `json:"clean,omitempty"`
570	}
571	
572	func (c mediaHealthVisibility) Run(ctx context.Context, env *scan.Env) scan.Result {
573		var r scan.Result
574		finish := func(out scan.Result) scan.Result {
575			out.Observations, out.Fields = r.Observations, r.Fields
576			return out
577		}
578		r.Field("capability_required", "CAP_SYS_ADMIN on the NVMe or SCSI character device for SMART; the NVMe admin passthrough is gated by a capability check, not by group membership")
579		r.Field("remediation_note", "obtaining SMART here requires CAP_SYS_ADMIN — adding the account to the disk group would not grant it, and recommending that would be a wrong instruction")
580	
581		var signals []healthSignal
582		var adverse []string
583		readableCount := 0
584	
585		// ext4 error counters.
586		if devs, obs := env.Files.ReadDirNames("/sys/fs/ext4", 64); obs.Status == probe.StatusOK {
587			r.Add(obs)
588			for _, d := range devs {
589				if d == "features" {
590					continue
591				}
592				for _, attr := range []string{"errors_count", "first_error_time", "lifetime_write_kbytes"} {
593					p := "/sys/fs/ext4/" + d + "/" + attr
594					v, o := env.Files.ReadTrimmed(p, probe.Tiny)
595					s := healthSignal{Path: p, Value: v, Errno: o.Reason()}
596					if o.Status == probe.StatusOK && attr == "errors_count" {
597						readableCount++
598						clean := v == "0"
599						s.Clean = &clean
600						if !clean {
601							adverse = append(adverse, "ext4 on "+d+" has recorded "+v+" filesystem error(s)")
602						}
603					}
604					signals = append(signals, s)
605				}
606			}
607		}
608	
609		// Device state and md degradation.
610		names, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
611		r.Add(blockObs)
612		for _, n := range names {
613			if hasAnyPrefix(n, excludedBlockPrefixes) {
614				continue
615			}
616			if strings.HasPrefix(n, "md") {
617				p := "/sys/block/" + n + "/md/degraded"
618				v, o := env.Files.ReadTrimmed(p, probe.Tiny)
619				s := healthSignal{Path: p, Value: v, Errno: o.Reason()}
620				if o.Status == probe.StatusOK {
621					readableCount++
622					clean := v == "0"
623					s.Clean = &clean
624					if !clean {
625						adverse = append(adverse, "md array "+n+" reports "+v+" degraded member(s)")
626					}
627				}
628				signals = append(signals, s)
629				continue
630			}
631			p := "/sys/block/" + n + "/device/state"
632			v, o := env.Files.ReadTrimmed(p, probe.Tiny)
633			if o.Status != probe.StatusOK {
634				continue
635			}
636			readableCount++
637			clean := v == "live" || v == "running"
638			signals = append(signals, healthSignal{Path: p, Value: v, Clean: &clean})
639			if !clean {
640				adverse = append(adverse, "device "+n+" reports state "+v)
641			}
642		}
643		r.Field("readable_signals", signals)
644	
645		// SMART, behind sysfs. Both tools are fallbacks and both are expected to be
646		// denied or absent; the errno is the evidence.
647		smartObtained := false
648		var smartAttempts []string
649		for _, n := range names {
650			if !strings.HasPrefix(n, "nvme") && !strings.HasPrefix(n, "sd") {
651				continue
652			}
653			obs := env.Runner.Run(ctx, probe.Spec{Name: "smartctl", Args: []string{"-H", "-j", "/dev/" + n},
654				Budget: 3000000000, Purpose: "drive health (JSON only; a tool that rejects -j yields unknown, never positional parsing)"})
655			r.Add(obs)
656			smartAttempts = append(smartAttempts, "smartctl -H -j /dev/"+n+" -> "+string(obs.Status)+" "+obs.Reason())
657			if obs.Status == probe.StatusOK && strings.Contains(obs.Value, "{") {
658				smartObtained = true
659				if strings.Contains(obs.Value, `"passed":false`) {
660					adverse = append(adverse, "SMART health self-assessment failed for /dev/"+n)
661				}
662				break
663			}
664			if strings.HasPrefix(n, "nvme") {
665				nobs := env.Runner.Run(ctx, probe.Spec{Name: "nvme", Args: []string{"smart-log", "/dev/" + n},
666					Budget: 3000000000, Purpose: "NVMe health (expected to be denied without CAP_SYS_ADMIN; the errno is the evidence)"})
667				r.Add(nobs)
668				smartAttempts = append(smartAttempts, "nvme smart-log /dev/"+n+" -> "+string(nobs.Status)+" "+nobs.Reason())
669				if nobs.Status == probe.StatusOK {
670					smartObtained = true
671					break
672				}
673			}
674			break
675		}
676		r.Field("smart_attempts", smartAttempts)
677		r.Field("smart_obtained", smartObtained)
678	
679		switch {
680		case len(adverse) > 0:
681			return finish(scan.Fail(scan.ReasonPolicy,
682				"a readable health signal reports a problem: "+strings.Join(adverse, "; ")))
683		case smartObtained:
684			return finish(scan.Pass("drive health telemetry is readable by this account and reports no failure"))
685		case readableCount > 0:
686			return finish(scan.Unknown(scan.ReasonEACCES,
687				"SMART telemetry is not obtainable by this account ("+strings.Join(smartAttempts, "; ")+
688					"), so media health itself is unknown; the "+itoa(int64(readableCount))+
689					" readable adjacent signals are in evidence and are all clean, but a filesystem error counter is not media health"))
690		default:
691			return finish(scan.Unknown(scan.ReasonEACCES,
692				"no health signal was readable at all: SMART needs a capability this account does not have, and no filesystem or device-state counter could be read"))
693		}
694	}
