7		"lava-sensor-exercise/sensor/internal/probe"
8		"lava-sensor-exercise/sensor/internal/scan"
9	)
10	
11	// rootSSHDir is the conventional location of root's key material. It is a
12	// starting point, not an authority: where root's keys actually come from is
13	// what the daemon's effective authorizedkeysfile says.
14	const (
15		rootSSHDir       = "/root/.ssh"
16		rootAuthKeysPath = "/root/.ssh/authorized_keys"
17	)
18	
19	// sshRootLoginPolicy answers: can a remote party authenticate directly as root
20	// over SSH, on the policy the running daemon actually loaded?
21	type sshRootLoginPolicy struct{ meta }
22	
23	func (c sshRootLoginPolicy) Run(ctx context.Context, env *scan.Env) scan.Result {
24		var r scan.Result
25	
26		// 1. The oracle: the daemon's own effective configuration.
27		oracle := env.SSHD(ctx)
28		oracleVal, oracleHas := oracle.Value("permitrootlogin")
29		oracleOK := oracle.OK() && oracleHas
30	
31		// 2. The walker: always run, because it is the provenance source and the
32		//    cross-check, not merely a fallback (LD-5).
33		cfg := walkSSHDConfig(env.Files, sshdRootPath(env.Files))
34		res := cfg.Resolve("permitrootlogin")
35	
36		// Evidence first, verdict after: the observation is recorded whatever the
37		// verdict turns out to be.
38		oracleObs := oracle.Obs
39		oracleObs.LoadBearing = oracleOK
40		r.Add(oracleObs)
41		for i, obs := range cfg.Observations {
42			// Only the root config read can be load-bearing, and only when the
43			// walker is the source of the verdict. Marking a failed fallback
44			// load-bearing while the oracle answered would manufacture an unknown.
45			if i == 0 && !oracleOK && res.Found {
46				obs.LoadBearing = true
47			}
48			r.Add(obs)
49		}
50	
51		// 3. Reconcile. `sshd -G` prints without-password where the file says
52		//    prohibit-password; folding the spellings avoids a false CONTESTED.
53		normOracle := normalisePermitRootLogin(oracleVal)
54		normWalker := normalisePermitRootLogin(res.EffectiveValue)
55	
56		finish := func(out scan.Result) scan.Result {
57			out.Observations, out.Fields = r.Observations, r.Fields
58			return out
59		}
60	
61		var effective, source string
62		switch {
63		case oracleOK && res.Found && normOracle != normWalker:
64			r.Field("config_resolution", res)
65			r.Field("oracle_value", oracleVal)
66			r.Field("walker_value", res.EffectiveValue)
67			r.Field("conditional_blocks", cfg.MatchBlocks)
68			return finish(scan.Unknown(scan.ReasonContested, contestedDetail("permitrootlogin", oracleVal, res.EffectiveValue)))
69		case oracleOK:
70			effective, source = normOracle, "sshd -G (running daemon)"
71		case res.Found:
72			effective, source = normWalker, "configuration chain walk"
73		default:
74			// Nothing set it. A compiled-in default describes what a daemon would
75			// do, so it is only meaningful when there is a daemon: with neither an
76			// sshd binary nor a readable configuration, defaulting would invent a
77			// policy for software that is not installed.
78			if !sshdIsPresent(oracle, cfg) {
79				r.Field("config_resolution", res)
80				return finish(scan.Unknown(scan.ReasonUtilMiss, noDaemonDetail))
81			}
