133	// keyPathVerdict is the per-path evidence row of the key-material question.
134	type keyPathVerdict struct {
135		Path         string `json:"path"`
136		Status       string `json:"status"`
137		Errno        string `json:"errno,omitempty"`
138		Size         *int64 `json:"size,omitempty"`
139		Mode         *int64 `json:"mode,omitempty"`
