144	// keyBasedRootLogin decides the prohibit-password / forced-commands-only
145	// branch, where password login as root is refused but key login is not.
146	//
147	// Absence proven by a successful listing is evidence, not an unknown. This
148	// passes only when the daemon itself told us where root's keys would come from
149	// — `authorizedkeysfile` expanded for root, with `authorizedkeyscommand` and
150	// `trustedusercakeys` both none — AND every one of those paths is proven absent
151	// by a successful stat of its parent directory. When any of that cannot be
152	// established (the usual case on an unprivileged run: /root/.ssh is EACCES),
153	// root key login can neither be confirmed nor excluded, and the honest answer
154	// is unknown (R4 B2 trap (d); L39 under-claim rule).
155	func (c sshRootLoginPolicy) keyBasedRootLogin(ctx context.Context, env *scan.Env, r scan.Result, effective, source string) scan.Result {
156		finish := func(out scan.Result) scan.Result {
157			out.Observations, out.Fields = r.Observations, r.Fields
158			return out
159		}
160		policyNote := "the running policy permits root login by public key (permitrootlogin " + effective + ", per " + source + ")"
161	
162		oracle := env.SSHD(ctx)
163		rootHome := homeOf(env.Files, "root")
164		paths, akfSource := rootAuthorizedKeyPaths(oracle, rootHome)
165	
166		akc, akcKnown := oracle.Value("authorizedkeyscommand")
167		tuca, tucaKnown := oracle.Value("trustedusercakeys")
168	
169		checked := make([]keyPathVerdict, 0, len(paths))
170		allProvenAbsent := true
171		var undetermined probe.Observation
172	
173		for _, p := range paths {
174			keyObs := env.Files.Stat(p)
175			keyObs.Detail = "candidate root AuthorizedKeysFile (" + akfSource + ")"
176			keyObs.LoadBearing = true
177			parentObs := env.Files.Stat(parentDir(p))
178			parentObs.Detail = "parent of a candidate root AuthorizedKeysFile; a successful listing is what makes absence provable"
179			r.Add(parentObs, keyObs)
180	
181			v := keyPathVerdict{Path: p, Status: string(keyObs.Status), Errno: keyObs.Reason(), ParentStatus: string(parentObs.Status)}
182			if keyObs.Meta != nil {
183				v.Size, v.Mode = keyObs.Meta.Size, keyObs.Meta.Mode
184			}
185			switch {
186			case keyObs.Status == probe.StatusOK && keyObs.Meta != nil && keyObs.Meta.Size != nil && *keyObs.Meta.Size > 0:
187				checked = append(checked, v)
188				r.Field("authorized_keys_checked", checked)
189				return finish(scan.Fail(scan.ReasonPolicy,
190					policyNote+" and root key material is present at "+p+" ("+itoa(*keyObs.Meta.Size)+" bytes)"))
191			case keyObs.Status == probe.StatusENOENT && parentObs.Status == probe.StatusOK:
192				// Absent, and the parent listing succeeded: a proven negative.
193				v.ProvenAbsent = true
194			case keyObs.Status == probe.StatusOK:
195				// Present and empty: no key material to authenticate with.
196				v.ProvenAbsent = true
197			default:
198				allProvenAbsent = false
199				if undetermined.Status == "" {
200					undetermined = keyObs
201				}
202			}
203			checked = append(checked, v)
204		}
