206		r.Field("authorized_keys_checked", checked)
207		r.Field("authorized_keys_source", akfSource)
208		r.Field("authorized_keys_command", renderDirective(akc, akcKnown))
209		r.Field("trusted_user_ca_keys", renderDirective(tuca, tucaKnown))
210		r.Field("root_home", rootHome)
