227				reason = undetermined.Reason()
228			}
229			return finish(scan.Unknown(reason,
230				policyNote+" and at least one candidate AuthorizedKeysFile path could not be resolved ("+reason+
231					"), so root key material can neither be confirmed nor excluded; denied is not absent"))
232		case !akcNone || !tucaNone:
233			what := "authorizedkeyscommand " + renderDirective(akc, akcKnown)
234			if !tucaNone {
235				what = "trustedusercakeys " + renderDirective(tuca, tucaKnown)
236			}
237			return finish(scan.Unknown(scan.ReasonPolicy,
238				policyNote+"; no key file exists at any path the daemon named, but "+what+
239					" can supply root keys from outside the filesystem paths we checked"))
240		default:
241			return finish(scan.Pass(policyNote + ", but root has no key material it could use: " + akfSource +
242				" resolves to " + strings.Join(paths, ", ") + ", each proven absent by a successful listing of its parent, " +
243				"authorizedkeyscommand is none and trustedusercakeys is none, so no remote party can authenticate as root over SSH"))
