247	// rootAuthorizedKeyPaths expands the daemon's effective authorizedkeysfile for
248	// root. OpenSSH resolves a relative path against the user's home directory and
249	// substitutes %h (home), %u (user name) and %% (a literal percent).
250	func rootAuthorizedKeyPaths(oracle *scan.SSHDOracle, rootHome string) (paths []string, source string) {
251		if v, ok := oracle.Value("authorizedkeysfile"); ok && strings.TrimSpace(v) != "" {
252			source = "sshd -G authorizedkeysfile"
253			for _, tok := range splitArgs(v) {
254				if isNoneValue(tok) {
255					continue
256				}
257				paths = append(paths, expandAuthorizedKeysToken(tok, rootHome))
258			}
259		}
260		if len(paths) == 0 {
261			source = "default AuthorizedKeysFile path (the daemon did not report one)"
262			paths = []string{rootHome + "/.ssh/authorized_keys"}
263		}
264		return paths, source
265	}
