267	func expandAuthorizedKeysToken(tok, home string) string {
268		var b strings.Builder
269		for i := 0; i < len(tok); i++ {
270			if tok[i] == '%' && i+1 < len(tok) {
271				switch tok[i+1] {
272				case 'h':
273					b.WriteString(home)
274					i++
275					continue
276				case 'u':
277					b.WriteString("root")
278					i++
279					continue
280				case '%':
281					b.WriteByte('%')
282					i++
283					continue
284				}
285			}
286			b.WriteByte(tok[i])
287		}
288		out := b.String()
289		if !strings.HasPrefix(out, "/") {
290			out = home + "/" + out
291		}
292		return out
293	}
