295	// homeOf resolves an account's home directory from /etc/passwd. No exec, and a
296	// documented convention rather than a guess when the file cannot be read.
297	func homeOf(f probe.Files, user string) string {
298		obs := f.Read("/etc/passwd", probe.Large)
299		if obs.Status == probe.StatusOK {
300			for _, ln := range strings.Split(obs.Value, "\n") {
301				fields := strings.Split(strings.TrimSpace(ln), ":")
302				if len(fields) >= 6 && fields[0] == user && fields[5] != "" {
303					return strings.TrimRight(fields[5], "/")
304				}
305			}
306		}
307		if user == "root" {
308			return rootHomeDefault
309		}
310		return "/home/" + user
311	}
312	
313	const rootHomeDefault = "/root"
314	
315	func parentDir(p string) string {
316		if i := strings.LastIndexByte(p, '/'); i > 0 {
317			return p[:i]
318		}
319		return "/"
320	}
