337	// conflictingMatch returns a Match-scoped occurrence whose verdict class
338	// differs from the global one. A Match that is strictly more restrictive does
339	// not invalidate a global fail.
340	func conflictingMatch(res sshdResolution, global string) (sshdOccurrence, bool) {
341		for _, occ := range res.ConditionalBlocks {
342			if verdictClass(normalisePermitRootLogin(occ.Value)) != verdictClass(global) {
343				return occ, true
344			}
345		}
346		return sshdOccurrence{}, false
