361	// sshdIsPresent reports whether there is evidence of an SSH daemon at all: a
362	// binary that could be executed, or a configuration chain that was read.
363	func sshdIsPresent(oracle *scan.SSHDOracle, cfg *sshdConfig) bool {
364		if oracle.Obs.Status != probe.StatusUtilityMissing {
365			return true
366		}
