370	// unresolvedReason picks the reason that is actually actionable.
371	//
372	// A daemon that exists but did not answer inside its budget (TIMEOUT) or failed
373	// for its own reasons (EXECUTION_ERROR) is a stronger signal than "the config
374	// file is not there", so it wins; a missing binary is weaker than a denied or
375	// absent config chain, so the chain wins over it.
376	func unresolvedReason(oracle *scan.SSHDOracle, cfg *sshdConfig) string {
377		switch oracle.Obs.Status {
378		case probe.StatusTimeout, probe.StatusExecError:
379			if r := oracle.Obs.Reason(); r != "" {
380				return r
381			}
382		}
383		if cfg.RootObs.Status != probe.StatusOK && cfg.RootObs.Status != "" {
384			if r := cfg.RootObs.Reason(); r != "" {
385				return r
386			}
387		}
388		if r := oracle.Obs.Reason(); r != "" {
389			return r
390		}
391		return scan.ReasonENOENT
392	}
