398		}
399		if cfg.RootObs.Status == probe.StatusOK {
400			parts = append(parts, "the config chain was read ("+strings.Join(cfg.Files, ", ")+
401				") but does not set the directive, and no compiled-in default is citable for this distribution")
402		} else {
403			parts = append(parts, cfg.RootPath+": "+string(cfg.RootObs.Status))
404		}
