445	func itoa(n int64) string {
446		if n == 0 {
447			return "0"
448		}
449		neg := n < 0
450		if neg {
451			n = -n
452		}
453		var b [20]byte
454		i := len(b)
455		for n > 0 {
456			i--
457			b[i] = byte('0' + n%10)
458			n /= 10
459		}
460		if neg {
461			i--
462			b[i] = '-'
463		}
464		return string(b[i:])
465	}
